package org.local.donusturucu;
import android.graphics.*;import android.graphics.pdf.PdfDocument;import java.io.*;import java.util.*;import org.json.*;
final class FeatureSelfTest {
 static void run(final MainActivity a,boolean speech)throws Exception {
  File root=new File(a.getExternalFilesDir(null),"feature-test");root.mkdirs();JSONArray rows=new JSONArray();
  OcrEngine.Host host=new OcrEngine.Host(){public void check(){}public void progress(int n,int total){a.message("OCR test "+n+"/"+total);}};
  for(String lang:new String[]{"eng","tur","kmr","ara","fas"}){JSONObject row=new JSONObject();row.put("action","ocr:"+lang);try{File image=new File(root,lang+".png");AndroidSelfTest.copy(a,"ocr-"+lang+".png",image);String text=new OcrEngine(a,host).read(image,"image",lang);String expected=lang.equals("ara")?"مرحبا":lang.equals("fas")?"سلام":lang.equals("kmr")?"Silav":lang.equals("tur")?"Merhaba":"Offline";if(!text.toLowerCase(Locale.ROOT).contains(expected.toLowerCase(Locale.ROOT)))throw new IOException("OCR mismatch: "+text);row.put("text",text);row.put("pass",true);}catch(Exception e){row.put("pass",false);row.put("error",e.toString());}rows.put(row);write(root,rows);}
  JSONObject pdfrow=new JSONObject();pdfrow.put("action","ocr:scanned-pdf");try{File image=new File(root,"tur.png");Bitmap bitmap=BitmapFactory.decodeFile(image.getAbsolutePath());PdfDocument pdf=new PdfDocument();for(int i=0;i<2;i++){PdfDocument.Page p=pdf.startPage(new PdfDocument.PageInfo.Builder(bitmap.getWidth(),bitmap.getHeight(),i+1).create());p.getCanvas().drawBitmap(bitmap,0,0,null);pdf.finishPage(p);}File file=new File(root,"scan.pdf");FileOutputStream out=new FileOutputStream(file);pdf.writeTo(out);out.close();pdf.close();bitmap.recycle();String text=new OcrEngine(a,host).read(file,"pdf","tur+eng");if(text.split("Merhaba",-1).length<3||text.contains("Page 1"))throw new IOException("Scanned PDF mismatch: "+text);File target=DocumentEngine.write(text,"docx",root);if(!DocumentEngine.read(target,"docx").contains("Merhaba"))throw new IOException("OCR document export failed");pdfrow.put("text",text);pdfrow.put("pass",true);}catch(Exception e){pdfrow.put("pass",false);pdfrow.put("error",e.toString());}rows.put(pdfrow);write(root,rows);
  if(speech)for(String language:new String[]{"en","tr","silence"}){JSONObject row=new JSONObject();row.put("action","speech:"+language);try{File input=new File(root,language+".wav");if(language.equals("silence"))a.execute(new ArrayList<String>(Arrays.asList("ffmpeg","-v","error","-f","lavfi","-i","anullsrc=r=16000:cl=mono","-t","4","-y",input.getAbsolutePath())));else AndroidSelfTest.copy(a,language.equals("tr")?"turkish-test.wav":"english-test.mp3",input);File work=new File(root,"speech-"+language);work.mkdirs();String text=new SpeechEngine(a,new SpeechEngine.Host(){public void check(){}public void run(List<String>args)throws Exception{a.execute(args);}public void progress(double n,double total){a.message("Speech test "+(int)n+"/"+(int)total);}}).read(input,language.equals("tr")?"tr":"en",0,-1,work);if(language.equals("silence")){if(text.length()>0)throw new IOException("Hallucinated silence: "+text);}else if(!text.toLowerCase(Locale.ROOT).contains(language.equals("tr")?"merhaba":"could you repeat that"))throw new IOException("Speech mismatch: "+text);row.put("text",text);row.put("pass",true);}catch(Exception e){row.put("pass",false);row.put("error",e.toString());}rows.put(row);write(root,rows);}
  if(speech){
   for(final String kind:new String[]{"interval","video","cancel"}){JSONObject row=new JSONObject();row.put("action","speech:"+kind);try{File input=new File(root,"en.wav");if(kind.equals("video")){File video=new File(root,"spoken-video.mp4");a.execute(new ArrayList<String>(Arrays.asList("ffmpeg","-v","error","-f","lavfi","-i","color=c=blue:s=160x120:r=10:d=4","-i",input.getAbsolutePath(),"-shortest","-c:v","libx264","-c:a","aac","-y",video.getAbsolutePath())));input=video;}
    final java.util.concurrent.atomic.AtomicBoolean cancelled=new java.util.concurrent.atomic.AtomicBoolean(false);SpeechEngine.Host host2=new SpeechEngine.Host(){public void check()throws Exception{if(cancelled.get())throw new InterruptedIOException("Cancelled");}public void run(List<String>args)throws Exception{a.execute(args);}public void progress(double n,double total){if(kind.equals("cancel"))cancelled.set(true);}};File work=new File(root,"extra-"+kind);work.mkdirs();boolean stopped=false;String text="";try{text=new SpeechEngine(a,host2).read(input,"en",kind.equals("interval")?.05:0,kind.equals("interval")?3:-1,work);}catch(InterruptedIOException e){if(!kind.equals("cancel"))throw e;stopped=true;}if(kind.equals("cancel")){if(!stopped)throw new IOException("Cancellation ignored");}else if(!text.toLowerCase(Locale.ROOT).contains("repeat that"))throw new IOException("Missing selected speech: "+text);row.put("text",text);row.put("pass",true);}catch(Exception e){row.put("pass",false);row.put("error",e.toString());}rows.put(row);write(root,rows);}
  }
  a.message("Feature tests complete: "+rows.length());
 }
 static void rich(final MainActivity a)throws Exception{
  File root=new File(a.getExternalFilesDir(null),"rich-test");root.mkdirs();JSONArray rows=new JSONArray();final RichDocument.Host host=new RichDocument.Host(){public void check(){}};
  for(String input:new String[]{"docx","odt","pptx"}){File source=new File(root,"source."+input);AndroidSelfTest.copy(a,"rich."+input,source);
   for(String format:new String[]{"docx","odt","epub","html","pdf"}){JSONObject row=new JSONObject();row.put("action",input+"→"+format);try{RichDocument rich=RichDocument.read(source,input,host);int count=0;for(RichDocument.Block b:rich.blocks)if(b.image!=null)count++;if(count<(input.equals("pptx")?2:1))throw new IOException("Missing input images: "+count);File folder=new File(root,input+"-"+format);folder.mkdirs();File output=rich.write(format,folder,host);if(!DocumentEngine.read(output,format).contains("Merhaba"))throw new IOException("Missing text in output");if(format.equals("pdf")){com.tom_roush.pdfbox.pdmodel.PDDocument pdf=com.tom_roush.pdfbox.pdmodel.PDDocument.load(output);int images=0;try{for(com.tom_roush.pdfbox.pdmodel.PDPage p:pdf.getPages())for(com.tom_roush.pdfbox.cos.COSName n:p.getResources().getXObjectNames())if(p.getResources().getXObject(n) instanceof com.tom_roush.pdfbox.pdmodel.graphics.image.PDImageXObject)images++;}finally{pdf.close();}if(images<count)throw new IOException("Missing PDF images");}else{RichDocument back=RichDocument.read(output,format,host);int images=0;for(RichDocument.Block b:back.blocks)if(b.image!=null)images++;if(images<count)throw new IOException("Missing roundtrip images: "+images);}row.put("images",count);row.put("pass",true);}catch(Exception e){row.put("pass",false);row.put("error",e.toString());}rows.put(row);write(root,rows);a.message("Rich document test: "+rows.length());}
  }a.message("Rich document tests complete: "+rows.length());
 }
 static void write(File root,JSONArray rows)throws Exception{JSONObject report=new JSONObject();report.put("cases",rows.length());int failures=0;for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getBoolean("pass"))failures++;report.put("failures",failures);report.put("rows",rows);Writer out=new OutputStreamWriter(new FileOutputStream(new File(root,"report.json")),"UTF-8");out.write(report.toString(2));out.close();}
}
